    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.closes = {symbol: RollingWindow[float](101) for symbol in self.symbols.values()}
        self.opens = {symbol: RollingWindow[float](2) for symbol in self.symbols.values()}

        self.aapl_rsi = self.rsi(
            self.symbols["AAPL"],
            14,
            MovingAverageType.WILDERS,
            Resolution.DAILY
        )

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.strategy_a_pending = False
        self.strategy_b_pending = False

    def on_data(self, data: Slice):
        # Keep market-state histories updating whenever individual bars exist.
        for symbol in self.symbols.values():
            if data.bars.contains_key(symbol):
                bar = data.bars[symbol]
                self.closes[symbol].add(float(bar.close))
                self.opens[symbol].add(float(bar.open))

        # Rule evaluation is skipped unless every subscribed ticker has today's bar.
        if any(not data.bars.contains_key(symbol) for symbol in self.symbols.values()):
            return

        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        # Sells are evaluated before buys.
        if self.strategy_a_lot > 0 and not self.strategy_a_pending:
            if self._spy_downward_sma_cross():
                self.strategy_a_pending = True
                self.market_order(spy, -self.strategy_a_lot, tag="Strategy A sell")

        if self.strategy_b_lot > 0 and not self.strategy_b_pending:
            if self.aapl_rsi.is_ready and self.aapl_rsi.current.value > 60:
                self.strategy_b_pending = True
                self.market_order(aapl, -self.strategy_b_lot, tag="Strategy B sell")

        if self.strategy_a_lot == 0 and not self.strategy_a_pending:
            if self._spy_upward_sma_cross():
                close = float(data.bars[spy].close)
                quantity = int((self.portfolio.total_portfolio_value * 0.40) // close)
                if quantity > 0:
                    self.strategy_a_pending = True
                    self.market_order(spy, quantity, tag="Strategy A buy")

        if self.strategy_b_lot == 0 and not self.strategy_b_pending:
            if self._aapl_red_for_three_days() and self.aapl_rsi.is_ready:
                close = float(data.bars[aapl].close)
                if self.portfolio.cash >= 20_000:
                    quantity = int(20_000 // close)
                    if quantity > 0:
                        self.strategy_b_pending = True
                        self.market_order(aapl, quantity, tag="Strategy B buy")

    def on_order_event(self, order_event: OrderEvent):
        if order_event.status not in [OrderStatus.FILLED, OrderStatus.PARTIALLY_FILLED]:
            if order_event.status in [OrderStatus.CANCELED, OrderStatus.INVALID]:
                if order_event.symbol == self.symbols["SPY"]:
                    self.strategy_a_pending = False
                elif order_event.symbol == self.symbols["AAPL"]:
                    self.strategy_b_pending = False
            return

        order = self.transactions.get_order_by_id(order_event.order_id)
        if order is None:
            return

        if order.tag.startswith("Strategy A"):
            self.strategy_a_lot += order_event.fill_quantity
            if order_event.status == OrderStatus.FILLED:
                self.strategy_a_pending = False

        elif order.tag.startswith("Strategy B"):
            self.strategy_b_lot += order_event.fill_quantity
            if order_event.status == OrderStatus.FILLED:
                self.strategy_b_pending = False

    def _spy_upward_sma_cross(self):
        closes = self.closes[self.symbols["SPY"]]
        if closes.count < 101:
            return False

        today_close = closes[0]
        yesterday_close = closes[1]
        today_sma = sum(closes[i] for i in range(100)) / 100.0
        yesterday_sma = sum(closes[i] for i in range(1, 101)) / 100.0

        return yesterday_close <= yesterday_sma and today_close > today_sma

    def _spy_downward_sma_cross(self):
        closes = self.closes[self.symbols["SPY"]]
        if closes.count < 101:
            return False

        today_close = closes[0]
        yesterday_close = closes[1]
        today_sma = sum(closes[i] for i in range(100)) / 100.0
        yesterday_sma = sum(closes[i] for i in range(1, 101)) / 100.0

        return yesterday_close >= yesterday_sma and today_close < today_sma

    def _aapl_red_for_three_days(self):
        closes = self.closes[self.symbols["AAPL"]]
        if closes.count < 4:
            return False

        return (
            closes[0] < closes[1] and
            closes[1] < closes[2] and
            closes[2] < closes[3]
        )
