from AlgorithmImports import *
import math


class IndependentSpyAndAaplStrategies(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_closes = RollingWindow[float](101)
        self.aapl_closes = RollingWindow[float](4)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.lots = {"A": 0, "B": 0}
        self.pending = {}
        self.order_owner = {}

    def OnData(self, data):
        if data.Bars.ContainsKey(self.spy):
            self.spy_closes.Add(data.Bars[self.spy].Close)

        if data.Bars.ContainsKey(self.aapl):
            self.aapl_closes.Add(data.Bars[self.aapl].Close)

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        if (not self.spy_closes.IsReady or
                not self.aapl_closes.IsReady or
                not self.aapl_rsi.IsReady):
            return

        # Evaluate all sells before any buys.
        if self.lots["A"] > 0 and "A" not in self.pending:
            if self._spy_downward_sma_cross():
                self._submit_order(self.spy, -self.lots["A"], "A", "strategy_a_sell")

        if self.lots["B"] > 0 and "B" not in self.pending:
            if self.aapl_rsi.Current.Value > 60:
                self._submit_order(self.aapl, -self.lots["B"], "B", "strategy_b_sell")

        if self.lots["A"] == 0 and "A" not in self.pending:
            if self._spy_upward_sma_cross():
                close = data.Bars[self.spy].Close
                quantity = int(math.floor(
                    0.40 * self.Portfolio.TotalPortfolioValue / close
                ))
                if quantity > 0:
                    self._submit_order(self.spy, quantity, "A", "strategy_a_buy")

        if self.lots["B"] == 0 and "B" not in self.pending:
            if self._aapl_red_for_three_days() and self.Portfolio.Cash >= 20_000:
                close = data.Bars[self.aapl].Close
                quantity = int(math.floor(20_000 / close))
                if quantity > 0:
                    self._submit_order(self.aapl, quantity, "B", "strategy_b_buy")

    def OnOrderEvent(self, order_event):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        owner = self.order_owner.get(order_event.OrderId)

        if owner is None and order is not None:
            if order.Tag.startswith("strategy_a_"):
                owner = "A"
            elif order.Tag.startswith("strategy_b_"):
                owner = "B"

        if owner is not None and order_event.FillQuantity != 0:
            self.lots[owner] = max(
                0,
                self.lots[owner] + order_event.FillQuantity
            )

        if owner is not None and order_event.Status in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]:
            self.pending.pop(owner, None)

    def _submit_order(self, symbol, quantity, owner, tag):
        self.pending[owner] = -1
        ticket = self.MarketOrder(symbol, quantity, tag=tag)
        self.order_owner[ticket.OrderId] = owner

        if self.pending.get(owner) == -1:
            self.pending[owner] = ticket.OrderId

    def _spy_upward_sma_cross(self):
        current_close = self.spy_closes[0]
        previous_close = self.spy_closes[1]
        current_sma = sum(self.spy_closes[i] for i in range(100)) / 100
        previous_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100

        return current_close > current_sma and previous_close <= previous_sma

    def _spy_downward_sma_cross(self):
        current_close = self.spy_closes[0]
        previous_close = self.spy_closes[1]
        current_sma = sum(self.spy_closes[i] for i in range(100)) / 100
        previous_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100

        return current_close < current_sma and previous_close >= previous_sma

    def _aapl_red_for_three_days(self):
        return (
