            if self.aapl_rsi.Current.Value > 60:
                self._submit_order(self.aapl, -self.lots["B"], "B", "strategy_b_sell")

        if self.lots["A"] == 0 and "A" not in self.pending:
            if self._spy_upward_sma_cross():
                close = data.Bars[self.spy].Close
                quantity = int(math.floor(
                    0.40 * self.Portfolio.TotalPortfolioValue / close
                ))
                if quantity > 0:
